import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`local-pr-outreach`,heroTitle:`Land local press coverage in minutes`,heroSubtitle:`Perplexity Computer researches your market, finds relevant journalists and creators, and drafts personalized pitches with a follow-up tracker — automatically.`,inputUrlCta:`Build my media list`,inputUrlPlaceholder:`yourbusiness.com`,inputUrlPrefill:`Go to {url} and analyze the business — extract the brand, industry, location, target audience, products/services, and any recent news or story angles. Then do the following: 1) Identify the city and region the business operates in. 2) Research and compile a list of 30+ relevant local media contacts — journalists at local newspapers and TV stations, editors at regional magazines, local newsletter operators, community bloggers, local podcast hosts, event organizers, and relevant local creators or influencers. For each contact, include their name, outlet, beat/focus area, contact method, and why they're a fit. 3) Draft 5 personalized pitch emails tailored to different contact types (e.g., news journalist, lifestyle blogger, newsletter curator, podcast host, event organizer) — each referencing the business's story angle and why it's relevant to that contact's audience. 4) Create a follow-up tracker spreadsheet with columns for contact name, outlet, pitch sent date, follow-up date, status, and notes. 5) Write a 2-week outreach calendar with recommended send times and follow-up cadence. 6) Include 3 alternative story angles the business could pitch based on local trends and seasonal hooks.`,heroOverlaySteps:[`Analyzing your business, location, and story angles`,`Researching local journalists, bloggers, newsletters, and creators`,`Drafting personalized pitches for each contact type`,`Media list, pitches, and follow-up tracker — ready to send`],generatingSteps:[`Visiting {url} to extract your brand, location, audience, and story angles`,`Designing an agent to find local journalists, newsletters, bloggers, and creators in your market`,`Configuring personalized pitch drafts and alternative story angles for each contact type`,`Setting up your follow-up tracker and 2-week outreach calendar`],featureSectionTitle:`From business URL to local media blitz`,featureCardTitles:[`Connects to your PR stack`,`Outputs you can send today`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Gmail, Google Sheets, Notion, Slack, Google Drive — Computer builds your media lists and sends pitches through the tools you already use.`,`Targeted media lists with 30+ contacts. Personalized pitch emails by contact type. Alternative story angles. A follow-up tracker and 2-week outreach calendar.`],capabilitySectionTitle:`Your PR team, on autopilot`,capabilitySectionSubtitle:`Enter your URL, step away, come back to a full local outreach campaign.`,capabilityCards:[{title:`Media Research`,description:`Computer can find local journalists, newsletter operators, bloggers, podcast hosts, and creators — filtered by beat, relevance, and proximity to your market.`},{title:`Personalized Pitches`,description:`Computer can draft tailored pitch emails for each contact type — referencing their past coverage, audience, and why your story matters to them.`},{title:`Story Angle Generation`,description:`Computer can analyze local trends, seasonal hooks, and your business news to surface multiple story angles that increase your odds of coverage.`},{title:`Connect Your Tools`,description:`Computer can push media lists to Google Sheets, draft pitches in Gmail, log outreach in Notion, and notify your team in Slack — all in one workflow.`},{title:`Remember & Learn`,description:`Computer can remember your contacts, past pitches, and response rates across sessions — so every outreach round builds on what worked before.`},{title:`Monitor & Alert`,description:`Computer can track follow-up deadlines, flag journalist responses, and surface new local media opportunities as they appear.`}]});export{t as default};
